insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/HOU/2026/03717', 'greystones, nottington lane|dt34bj', 'Greystones, Nottington Lane', 'Weymouth', 'DT3 4BJ', 4.8, 'Extension to create a garden room + raising the garage roof', '["I noticed your recent plans in Weymouth to extend and create a garden room, along with raising the garage roof. It looks like a lovely way to gain a bright, usable space, and as a local, family-run builder just up the road in Broadmayne I wanted to introduce ourselves.", "Garden rooms are some of our favourite work — the joinery, the glazing, and how the space opens onto the garden are where the quality really shows. Tie that in with the garage roof and it makes for one coordinated project, which is exactly the kind of thing we’ve been doing across Dorset for over 30 years.", "There’s no hard sell here — just an offer of a no-obligation chat once you’re ready to think about the build. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=429913', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/HOU/2026/03842', 'seagrove, main road|bh205rj', 'Seagrove, Main Road', 'West Lulworth', 'BH20 5RJ', 7.9, 'Raised patio / deck to the rear garden (landscaping)', '["I noticed your recent plans in West Lulworth for a raised patio and deck to the rear garden. It’s the kind of project that really changes how you enjoy outdoor space, and as a local, family-run builder we wanted to introduce ourselves.", "Good hard landscaping is all in the detail — levels, drainage, and timber that’s built to last. With our landscaping side we handle decks, terraces and garden levels as one tidy job rather than several trades to juggle.", "No pressure at all — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=430061', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/HOU/2026/03588', 'jasmine cottage, the square|dt20jd', 'Jasmine Cottage, The Square', 'Cattistock', 'DT2 0JD', 10.9, 'Remove rear porch, new single-storey rear extension', '["I noticed your recent plans at Cattistock to remove the rear porch and build a single-storey rear extension. It’s a smart way to gain proper space, and as a local, family-run builder in Broadmayne I wanted to introduce ourselves.", "The details that matter most later are the ones you don’t see — how the new roof ties into the existing structure, and how the finish sits with the character of the cottage. That careful carpentry is exactly what we do, working closely with you from first sketch to final sign-off.", "There’s no hard sell here — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=429759', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/FUL/2026/03847', '15 & 18 shadrach|dt64qf', '15 & 18 Shadrach', 'Burton Bradstock', 'DT6 4QF', 14.5, 'New porch, side and rear extensions', '["I noticed your recent plans in Burton Bradstock for a new porch along with side and rear extensions. It looks like a well-considered project, and as a family-run building firm we wanted to introduce ourselves before the work begins.", "The porch is exactly the sort of thing we most enjoy — we do a lot of bespoke timber porches, and they set the tone for the whole front of a house. On the extensions, the joinery and how the new work meets the old are where careful carpentry earns its keep.", "No pressure at all — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=429743', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/HOU/2026/03852', '8 barr lane|dt64px', '8 Barr Lane', 'Burton Bradstock', 'DT6 4PX', 14.7, 'Rear first-floor extension', '["I noticed your recent plans in Burton Bradstock for a rear first-floor extension. Adding space upstairs is a great way to get more from a home without losing garden, and as a local, family-run builder we wanted to introduce ourselves.", "A first-floor extension lives or dies on the structural detail and the finish — how it ties into the existing roof and walls so it feels like it was always there. That’s exactly the kind of work we’ve been doing across Dorset for over 30 years.", "There’s no hard sell here — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=430070', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/HOU/2026/03509', 'delapre house, st andrews road|dt63bg', 'Delapre House, St Andrews Road', 'Bridport', 'DT6 3BG', 15.9, 'Single-storey side extension', '["I noticed your recent plans in Bridport for a single-storey side extension. It’s a lovely way to open up the ground floor, and as a family-run building firm we wanted to introduce ourselves before the work begins.", "The joinery around the glazing and how the new work blends with the existing house are where the quality really shows, and that’s exactly what we’ve been doing across Dorset for over 30 years — working closely with you from first sketch to final sign-off.", "No pressure at all — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=429671', '2026-W30', 'pending')
