insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/26/03270/CLP', '3 sandy lane|bh165eh', '3 Sandy Lane', 'Poole', 'BH16 5EH', 16.6, 'Demolish garage & build new (permitted development, about to start)', '["I noticed your recent plans at West Parley to demolish the existing garage and build new. A lawful development certificate usually means a project that’s ready to go, so as a local, family-run builder we wanted to introduce ourselves at the right moment.", "Rebuilding an outbuilding properly — good foundations, insulation and joinery — makes all the difference to how it looks and lasts. It’s exactly the kind of work we’ve been handling across Dorset for over 30 years.", "There’s no hard sell here — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.bcpcouncil.gov.uk/Planning/Display/P/26/03270/CLP', '2026-W30', 'pending')
on conflict (client_id, application_reference) do update set ai_summary=excluded.ai_summary, body=excluded.body, source_url=excluded.source_url;
insert into leads (client_id, application_reference, address_key, site_address, city, postcode, distance_miles, ai_summary, body, source_url, week_label, status) values ('kap', 'P/VOL/2026/03781', 'church farm, road to beer hackett|dt96qt', 'Church Farm, Road to Beer Hackett', 'Beer Hackett', 'DT9 6QT', 16.7, 'Single-storey rear extension with rooflights', '["I noticed your recent plans at Beer Hackett for a single-storey rear extension with new rooflights. Bringing light into a home like that makes a real difference, and as a local, family-run builder we wanted to introduce ourselves.", "The rooflights and how the new roof structure is framed are exactly the details we take care over, so the finished space feels like it was always part of the house. That’s the kind of work we’ve been doing across Dorset for over 30 years.", "No pressure at all — just an offer of a no-obligation chat once you’re ready. You can see examples of our work using the codes on this letter, or reach me any time on the details above."]'::jsonb, 'https://planning.dorsetcouncil.gov.uk/plandisp.aspx?recno=429991', '2026-W30', 'pending')
